import requests

url = "https://api.example.com/orders"

payload = {
    "id": "o-1",
    "items": [
        {
            "sku": "A",
            "qty": 2
        },
        {
            "sku": "B",
            "qty": 1
        }
    ],
    "customer": {
        "name": "Ada",
        "vip": True
    }
}
headers = {
    "accept": "application/json",
    "content-type": "application/json"
}

response = requests.post(url, json=payload, headers=headers)

print(response.text)
